<script setup>
import { ref } from 'vue'
const props=defineProps({modelValue:{type:Array,default:()=>[]},max:{type:Number,default:1},label:{type:String,default:'图片'},inputName:{type:String,default:''},disabled:Boolean})
const emit=defineEmits(['update:modelValue','busy'])
const draft=ref(''),error=ref(''),uploading=ref(false)
const update=items=>emit('update:modelValue',items)
function addUrl(){const url=draft.value.trim();if(!url||props.modelValue.length>=props.max)return;update([...props.modelValue,url]);draft.value=''}
function remove(index){update(props.modelValue.filter((_,item)=>item!==index))}
function move(index,direction){const target=index+direction;if(target<0||target>=props.modelValue.length)return;const next=[...props.modelValue];[next[index],next[target]]=[next[target],next[index]];update(next)}
async function upload(event){const file=event.target.files?.[0];event.target.value='';if(!file||uploading.value||props.disabled)return;uploading.value=true;emit('busy',true);error.value='';try{const body=new FormData();body.append('image',file);const response=await fetch('/api/admin/product-images',{method:'POST',credentials:'same-origin',body});const payload=await response.json();if(!response.ok)throw new Error(payload.error?.message||'图片上传失败');update([...props.modelValue,payload.data.url].slice(0,props.max))}catch(e){error.value=e.message}finally{uploading.value=false;emit('busy',false)}}
</script>
<template><div class="image-editor"><div v-for="(url,index) in modelValue" :key="url" class="image-row"><img :src="url" :alt="`${label} ${index+1}`"><div><input :name="index===0?inputName:undefined" :value="url" maxlength="1000" @input="update(modelValue.map((item,current)=>current===index?$event.target.value:item))"><button type="button" :disabled="disabled" @click="remove(index)">删除</button><button v-if="max>1" type="button" :disabled="disabled||index===0" @click="move(index,-1)">上移</button><button v-if="max>1" type="button" :disabled="disabled||index===modelValue.length-1" @click="move(index,1)">下移</button></div></div><div v-if="modelValue.length<max" class="image-add"><input :value="draft" :name="modelValue.length===0?inputName:undefined" maxlength="1000" :placeholder="`粘贴${label}地址`" :disabled="disabled||uploading" @input="draft=$event.target.value;if(max===1)update(draft?[draft]:[])" @keydown.enter.prevent="addUrl"><button type="button" :disabled="disabled||uploading||!draft.trim()" @click="addUrl">添加地址</button><label>上传图片<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" :disabled="disabled||uploading" @change="upload"></label></div><p v-if="error" class="error" role="alert">{{ error }}</p></div></template>
<style scoped>.image-row{display:flex;gap:10px;margin-bottom:10px}.image-row img{width:72px;height:72px;object-fit:cover;border-radius:6px}.image-row div{flex:1}.image-row input,.image-add input{box-sizing:border-box;width:100%;padding:8px;border:1px solid #d7dfe4;border-radius:6px}.image-row button,.image-add button,.image-add label{margin:6px 6px 0 0;padding:6px 9px;border:1px solid #ccd5dc;border-radius:6px;background:#fff;color:#234b69;font:inherit;font-size:12px}.image-add{display:flex;gap:8px;flex-wrap:wrap}.image-add input{flex:1;min-width:180px}.image-add label{position:relative;overflow:hidden;margin:0}.image-add label input{position:absolute;inset:0;opacity:0;cursor:pointer}.error{color:#b42318;font-size:13px}</style>
